    static let raceJSON = #"""
{"id":"fmm_synthetic_race","feature_id":"fmf_synthetic","role":"assistant","text":"I don't have write/edit access in this session (only read/search tools), so here are the exact patched files to apply.\n\n### `src/inventory.js`\n\n```js\n// In-memory stock with async \"storage\" to mimic a database round trip.\nconst stock = new Map();\nconst reservations = new Map(); // reservationId -> { sku, qty }\nlet nextId = 1;\n\nconst delay = (ms) => new Promise((r) => setTimeout(r, ms));\n\n// Per-SKU async mutex. `locks` holds the tail of each SKU's promise chain;\n// every mutation for a SKU runs only after the previous one settles, so\n// read-modify-write sequences can no longer interleave.\nconst locks = new Map();\n\nfunction withSkuLock(sku, fn) {\n  const prev = locks.get(sku) ?? Promise.resolve();\n  const result = prev.then(fn, fn);\n  // The stored tail must never reject, or later waiters inherit the failure.\n  locks.set(sku, result.then(() => {}, () => {}));\n  return result;\n}\n\nexport function seed(entries) {\n  stock.clear();\n  reservations.clear();\n  for (const [sku, qty] of Object.entries(entries)) stock.set(sku, qty);\n}\n\nexport async function available(sku) {\n  await delay(5);\n  return stock.get(sku) ?? 0;\n}\n\nexport async function reserve(sku, qty) {\n  if (!Number.isInteger(qty) || qty <= 0) {\n    throw new Error(`Invalid quantity ${qty} for ${sku}`);\n  }\n  return withSkuLock(sku, async () => {\n    const have = await available(sku); // read and write both inside the lock\n    if (have < qty) throw new Error(`Only ${have} left of ${sku}`);\n    await delay(5); // simulated write latency\n    stock.set(sku, have - qty);\n    const id = `r${nextId++}`;\n    reservations.set(id, { sku, qty });\n    return id;\n  });\n}\n\nexport async function release(id) {\n  const r = reservations.get(id);\n  if (!r) return;\n  return withSkuLock(r.sku, async () => {\n    if (!reservations.delete(id)) return; // idempotent, even when queued\n    stock.set(r.sku, (stock.get(r.sku) ?? 0) + r.qty);\n  });\n}\n\nexport function reservationCount() {\n  return reservations.size;\n}\n```\n\n### `src/checkout.js`\n\nThe other half of \"two people check out\" safety is that a failed checkout currently leaks its reservations — `charge` can throw `CardDeclined`, and a later cart line can throw, and neither path releases what came before.\n\n```js\nimport { reserve, release } from \"./inventory.js\";\nimport { charge } from \"./payments.js\";\n\nexport async function checkout(cart, card) {\n  const reservationIds = [];\n  try {\n    for (const line of cart.lines.values()) {\n      reservationIds.push(await reserve(line.sku, line.qty));\n    }\n    const amount = cart.total();\n    const receipt = await charge(card, amount);\n    return { receipt, reservationIds, amount };\n  } catch (err) {\n    // Roll back anything reserved before the failure (declined card,\n    // out-of-stock line, gateway error) so stock isn't leaked.\n    for (const id of reservationIds) await release(id);\n    throw err;\n  }\n}\n\nexport async function cancel(order) {\n  for (const id of order.reservationIds) await release(id);\n}\n```\n\n### Tests to add (`test/inventory.test.js`)\n\n```js\ntest(\"concurrent reserves never oversell\", async () => {\n  seed({ mug: 5 });\n  const results = await Promise.allSettled(\n    Array.from({ length: 20 }, () => reserve(\"mug\", 1)),\n  );\n  assert.equal(results.filter((r) => r.status === \"fulfilled\").length, 5);\n  assert.equal(await available(\"mug\"), 0);\n});\n```\n\nAnd in a checkout test: seed `{ mug: 3 }`, checkout a cart of 2 with card `\"4000000000000002\"`, assert it rejects with `/declined/`, then `available(\"mug\") === 3` and `reservationCount() === 0`.\n\n## Summary\n\n- **Not safe.** `reserve` reads stock, awaits, then writes a value derived from the stale read — two simultaneous buyers both pass the `have < qty` check and both succeed.\n- **Fix:** serialize each SKU's read-modify-write behind an async mutex (or, in a real database, one `UPDATE … WHERE qty >= n` / `SELECT … FOR UPDATE`), and route `release` through the same lock so an in-flight reserve can't clobber it.\n- **Related:** reject non-positive quantities, and release reservations when checkout fails.\n\nCaveats: I couldn't run `npm test` (no shell tool here), so please verify after applying. Also note this lock is per-process — it's correct for this in-memory store but does nothing once you run multiple instances behind a load balancer, which is exactly why the DB-level atomic conditional update is the durable fix.","status":"done","created_at":"2026-09-26T12:00:00Z","visibility":"conversation","skim":{"status":"ready","format":"breath_tight","prompt_version":"skim-v2","segmenter_version":1,"skim_version":1,"document":{"version":1,"format":"breath_tight","status":"answer","statusLabel":"Answer","headline":[],"blocks":[{"kind":"say","tokens":[{"t":"text","v":"It's "},{"t":"anchor","id":"a1","label":[{"t":"text","v":"not safe today"}],"refs":["s11"]},{"t":"text","v":" — two buyers can both pass the stock check; the fix is an "},{"t":"anchor","id":"a2","label":[{"t":"text","v":"async mutex per SKU"}],"refs":["s12"]},{"t":"text","v":" with patched "},{"t":"anchor","id":"a3","label":[{"t":"text","v":"inventory"}],"refs":["s2"]},{"t":"text","v":" and "},{"t":"anchor","id":"a4","label":[{"t":"text","v":"checkout"}],"refs":["s4"]},{"t":"text","v":" files ready to apply."}]},{"kind":"heads_up","tokens":[{"t":"text","v":"Couldn't run tests or apply the patch (read-only session), so verify after applying; the lock is per-process only."}]},{"kind":"ask","tokens":[{"t":"text","v":"Want me to also add the "},{"t":"anchor","id":"a5","label":[{"t":"text","v":"concurrency tests"}],"refs":["s8"]},{"t":"text","v":"?"}]}],"drawers":[],"rest":{"refs":["s1","s3","s5","s6","s9","s13","s14"]},"anchors":[{"id":"a1","label":"not safe today","refs":["s11"],"where":"block 1","kind":"text"},{"id":"a2","label":"async mutex pe